17	
18	var builder = WebApplication.CreateBuilder(args);
19	var env = builder.Environment;
20	
21	var frontUrl = builder.Configuration.GetValue<string>("FrontUrl")!;
22	var baseUrl = builder.Configuration.GetValue<string>("BaseUrl")!;
23	string? baseUrlPath = builder.Configuration["BaseUrlPath"]?.ToNullString();
24	
25	builder.Services.AddCoreServices();
26	
27	builder.Services.AddScoped<SignatureContext>();
28	
29	LogManager.Setup().SetupExtensions(ext =>
30	{
31	    ext.RegisterLayoutRenderer("trace-id", logevent => Activity.Current?.TraceId.ToString());
32	    ext.RegisterLayoutRenderer("spanId-id", logevent => Activity.Current?.SpanId.ToString());
33	});
34	
35	builder.Services.AddLogging((configure) =>
36	{
37	    configure.AddNLog("nlog.config");
38	});
39	
40	builder.Services.AddAuthentication(options =>
41	{
42	    options.DefaultScheme = CookieAuthenticationDefaults.AuthenticationScheme;
43	    options.DefaultChallengeScheme = Saml2Defaults.Scheme;
44	})
45	.AddCookie(options =>
46	{
47	    options.ExpireTimeSpan = TimeSpan.FromHours(8);
48	    //options.SlidingExpiration = true; // �ҥηưʹL��
49	})
50	.AddSaml2(options =>
51	{
52	    var env = builder.Environment;
53	    var certPath = Path.Combine(env.ContentRootPath, "App_Data", "sso.pfx");
54	    options.SPOptions.NameIdPolicy = new Saml2NameIdPolicy(true, NameIdFormat.Unspecified);
55	    options.SPOptions.EntityId = new EntityId(frontUrl);
56	    options.SPOptions.PublicOrigin = new Uri(frontUrl);
57	
58	    if (!string.IsNullOrEmpty(baseUrlPath))
59	    {
60	        options.SPOptions.ModulePath = $"/{baseUrlPath}/Saml2";
61	    }
62	
63	    options.SPOptions.ServiceCertificates.Add(new X509Certificate2(certPath, "612"));
64	    options.IdentityProviders.Add(new IdentityProvider(
65	        new EntityId("https://portal.aca.ntu.edu.tw/sso-gateway/"),
66	        options.SPOptions)
67	    {
68	        MetadataLocation = "https://portal.aca.ntu.edu.tw/sso-gateway/idp/metadata",
69	        LoadMetadata = true,
70	        AllowUnsolicitedAuthnResponse = true
71	    });
72	});
73	
74	builder.Services.AddControllersWithViews(config =>
75	{
76	    config.Filters.Add(typeof(ValidateSignatureFilter));
77	    config.Filters.Add(typeof(ValidateJWTFilter));
78	    config.Filters.Add(typeof(ExceptionFilter));
79	}).AddJsonOptions(options =>
80	{
81	    options.JsonSerializerOptions.Converters.Add(new JsonStringEnumConverter());
82	}).AddKebabCaseRouting();
83	
84	builder.Services.AddHttpClient("NoSsl", client =>
85	{
86	    client.Timeout = TimeSpan.FromSeconds(60 * 5);
87	}).ConfigurePrimaryHttpMessageHandler(() => new HttpClientHandler
88	    {
89	        ServerCertificateCustomValidationCallback = HttpClientHandler.DangerousAcceptAnyServerCertificateValidator
90	    });
91	
92	var policyDomains = builder.Configuration.GetSection("PolicyDomain").Get<string[]>();
93	var allowSpecificOrigins = "_allowSpecificOrigins";
94	
95	builder.Services.AddCors(options =>
96	{
97	    options.AddPolicy(name: allowSpecificOrigins,
98	        policy =>
99	        {
100	            policy.WithOrigins(policyDomains)
101	                  .AllowAnyHeader()
102	            .AllowAnyMethod();
103	        });
104	});
105	
106	var app = builder.Build();
107	var serviceProvider = app.Services;
108	var configuration = app.Configuration;
109	
110	DependencyInjection.Init(serviceProvider);
111	
112	AuthorizeManagement.Configure(serviceProvider);
113	JWTHelper.Configure(serviceProvider);
114	
115	// Configure the HTTP request pipeline.
116	if (!env.IsDevelopment())
117	{
118	    app.UseExceptionHandler("/Error");
119	    // The default HSTS value is 30 days. You may want to change this for production scenarios, see https://aka.ms/aspnetcore-hsts.
120	    app.UseHsts();
121	}
122	
123	if (!string.IsNullOrEmpty(baseUrlPath))
124	    app.UsePathBase($"/{baseUrlPath}");
125	
126	app.UseForwardedHeaders(new ForwardedHeadersOptions
127	{
128	    ForwardedHeaders = ForwardedHeaders.XForwardedFor | ForwardedHeaders.XForwardedProto | ForwardedHeaders.XForwardedHost
129	});
130	
131	app.UseDefaultFiles();
132	app.UseStaticFiles();
133	
134	app.UseCors(allowSpecificOrigins);
135	app.UseRouting();
136	app.UseAuthorization();
137	app.MapControllers();
138	
139	app.Run();
